pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();

        address dummy = address(0x1234);
        address payable dummyPayable = payable(dummy);
        c.updateRoundImplementation(dummyPayable);
        c.updateAlloSettings(dummy);


        c = new RoundFactory();
        c.initialize();

        bool success;
        try c.transferOwnership(address(0)) {
            success = true;
        } catch {
            success = false;
        }


        assertTrue(!success);
    }
}
